UPDATE ec_internal_pages SET intro_content='[{"_type":"block","_key":"k2l","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2k","text":"Choosing a hearing aid means matching the right device style and features to your hearing test results and your daily life.","marks":[]}]},{"_type":"block","_key":"k2n","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2m","text":"The right match improves speech clarity, comfort, and confidence, so you keep up in real conversations.","marks":[]}]},{"_type":"block","_key":"k2p","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2o","text":"New Leaf Hearing Care helps with choosing a hearing aid in Arvada, CO and Littleton, CO (formerly Columbine Hearing Care).","marks":[]}]},{"_type":"block","_key":"k2r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2q","text":"Choosing a hearing aid can feel overwhelming at first. There are many brands, styles, and features to choose from.","marks":[]}]},{"_type":"block","_key":"k2t","style":"normal","markDefs":[{"_type":"link","_key":"nlfit254","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"k2t_f0","text":"New Leaf Hearing Care keeps the process clear and personal. We start with your hearing test, then we match solutions to your needs, your comfort, and your goals. Once you''ve picked a device, the next step would be a hearing aid fitting. New Leaf Hearing Care provides professional ","marks":[]},{"_type":"span","_key":"k2t_f1","text":"hearing aid fitting in Arvada","marks":["nlfit254"]},{"_type":"span","_key":"k2t_f2","text":" and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"k2v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u","text":"You can visit us in Arvada, CO or Littleton, CO. The Littleton location is formerly Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]' WHERE slug='hearing-aids-products/choosing-a-hearing-aid' AND intro_content='[{"_type":"block","_key":"k2l","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2k","text":"Choosing a hearing aid means matching the right device style and features to your hearing test results and your daily life.","marks":[]}]},{"_type":"block","_key":"k2n","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2m","text":"The right match improves speech clarity, comfort, and confidence, so you keep up in real conversations.","marks":[]}]},{"_type":"block","_key":"k2p","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2o","text":"New Leaf Hearing Care helps with choosing a hearing aid in Arvada, CO and Littleton, CO (formerly Columbine Hearing Care).","marks":[]}]},{"_type":"block","_key":"k2r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2q","text":"Choosing a hearing aid can feel overwhelming at first. There are many brands, styles, and features to choose from.","marks":[]}]},{"_type":"block","_key":"k2t","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s","text":"New Leaf Hearing Care keeps the process clear and personal. We start with your hearing test, then we match solutions to your needs, your comfort, and your goals.","marks":[]}]},{"_type":"block","_key":"k2v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u","text":"You can visit us in Arvada, CO or Littleton, CO. The Littleton location is formerly Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]';
UPDATE ec_internal_pages SET content='[{"_type":"block","_key":"k13v","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k13u","text":"A Quick Tip Before You Compare Styles","marks":["strong"]}]},{"_type":"block","_key":"k13x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k13w","text":"A hearing aid style should match your hearing test results. It should also match how you live, work, and move through the day.","marks":[]}]},{"_type":"block","_key":"k13z","style":"normal","markDefs":[{"_type":"link","_key":"nlfit212","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"k13z_f0","text":"A good fit starts with a full hearing test and a real conversation. That is how the “best on paper” option becomes the best option for you. After you settle on a style, your ","marks":[]},{"_type":"span","_key":"k13z_f1","text":"hearing aid fittings in Arvada","marks":["nlfit212"]},{"_type":"span","_key":"k13z_f2","text":" appointment confirms the physical fit and programs the hearing aids to match your hearing needs.","marks":[]}]},{"_type":"block","_key":"k141","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k140","text":"The Main Hearing Aid Styles","marks":["strong"]}]},{"_type":"block","_key":"k143","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k142","text":"Most hearing aids fall into two broad groups.","marks":[]}]},{"_type":"block","_key":"k145","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k144","text":"Some styles sit behind the ear. Others sit in or near the ear canal.","marks":[]}]},{"_type":"block","_key":"k147","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k146","text":"Your audiologist will show you what each one feels like and how it works, then guide you toward the right match.","marks":[]}]},{"_type":"block","_key":"k149","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k148","text":"Behind-the-Ear (BTE)","marks":[]}]},{"_type":"block","_key":"k14b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14a","text":"A behind-the-ear hearing aid sits behind the ear. Sound travels through a small tube to an earmold or ear tip.","marks":[]}]},{"_type":"block","_key":"k14d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14c","text":"This style works for many levels of hearing loss. It also provides a stable fit for active days.","marks":[]}]},{"_type":"block","_key":"k14f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14e","text":"Many people like BTE styles because they feel secure. Cleaning can also feel simpler because the parts are easier to see and handle.","marks":[]}]},{"_type":"block","_key":"k14h","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14g","text":"Receiver-in-Canal (RIC)","marks":[]}]},{"_type":"block","_key":"k14j","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14i","text":"A receiver-in-canal style sits behind the ear, with a thin wire that connects to a small speaker in the ear canal.","marks":[]}]},{"_type":"block","_key":"k14l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14k","text":"RIC styles are popular because they feel light and open. Many people say the sound feels natural, especially for mild to moderate hearing loss.","marks":[]}]},{"_type":"block","_key":"k14n","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14m","text":"This style can also offer strong features for speech in noise and phone streaming. Your audiologist will help you choose the right receiver strength for your hearing needs.","marks":[]}]},{"_type":"block","_key":"k14p","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14o","text":"In-the-Ear (ITE)","marks":[]}]},{"_type":"block","_key":"k14r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14q","text":"An in-the-ear hearing aid sits inside the outer ear. The faceplate is visible, and the hearing aid is one piece.","marks":[]}]},{"_type":"block","_key":"k14t","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14s","text":"Some patients like ITE styles because they are easier to insert than smaller in-canal options. Handling can be simpler for people with limited finger strength.","marks":[]}]},{"_type":"block","_key":"k14v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14u","text":"ITE styles also keep everything in one place. That can feel less fussy for daily use.","marks":[]}]},{"_type":"block","_key":"k14x","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14w","text":"In-the-Canal (ITC)","marks":[]}]},{"_type":"block","_key":"k14z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14y","text":"An in-the-canal hearing aid sits partly in the ear canal. It is smaller than an ITE and less visible for many people.","marks":[]}]},{"_type":"block","_key":"k151","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k150","text":"Comfort and fit depend on your ear shape. Your audiologist will check if your ear canal size supports this option.","marks":[]}]},{"_type":"block","_key":"k153","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k152","text":"ITC styles can work well for people who want a smaller device while still keeping handling reasonable.","marks":[]}]},{"_type":"block","_key":"k155","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k154","text":"Completely-in-Canal (CIC)","marks":[]}]},{"_type":"block","_key":"k157","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k156","text":"A completely-in-canal hearing aid sits deeper in the ear canal and is designed to be less noticeable.","marks":[]}]},{"_type":"block","_key":"k159","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k158","text":"This style can be a good match for some people who want a discreet option. It requires good finger control for insertion and removal.","marks":[]}]},{"_type":"block","_key":"k15b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15a","text":"CIC styles also depend on ear canal shape and hearing needs. Your audiologist will confirm if this option fits your hearing profile.","marks":[]}]},{"_type":"block","_key":"k15d","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15c","text":"Hearing Aid Style Choice Is Not Only About Looks","marks":["strong"]}]},{"_type":"block","_key":"k15f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15e","text":"Many people start with “I want the smallest one.” That makes sense.","marks":[]}]},{"_type":"block","_key":"k15h","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15g","text":"However, daily success depends on comfort, clear sound, and easy use. A hearing aid that is hard to handle or does not match your hearing needs leads to less wear time.","marks":[]}]},{"_type":"block","_key":"k15j","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15i","text":"More wear time leads to better results. Our audiologists in Littleton, CO and Arvada, CO will help you choose a style you will use every day.","marks":[]}]},{"_type":"block","_key":"k15l","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15k","text":"Your Hearing Needs + Your Routine = The Right Style","marks":["strong"]}]},{"_type":"block","_key":"k15n","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15m","text":"Style choice is part hearing, part lifestyle. When choosing the best hearing aid style, we need to consider the following:","marks":[]}]},{"_type":"block","_key":"k15p","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15o","text":"Dexterity and vision","marks":[]}]},{"_type":"block","_key":"k15r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15q","text":"Small batteries and small buttons can be tough. Rechargeable options and larger styles can make daily use easier.","marks":[]}]},{"_type":"block","_key":"k15t","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15s","text":"Glasses and masks","marks":[]}]},{"_type":"block","_key":"k15v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15u","text":"Behind-the-ear styles can still work well with glasses. Your audiologist can adjust the fit and show you how to put them on in the right order.","marks":[]}]},{"_type":"block","_key":"k15x","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15w","text":"Work and hobbies","marks":[]}]},{"_type":"block","_key":"k15z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15y","text":"Meetings, phone calls, and noisy jobs require strong speech support. Music, fitness, and outdoor time can affect comfort needs.","marks":[]}]},{"_type":"block","_key":"k161","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k160","text":"Ear shape and comfort","marks":[]}]},{"_type":"block","_key":"k163","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k162","text":"Some ears do best with soft tips. Others need custom earmolds for a secure seal and stable sound.","marks":[]}]},{"_type":"block","_key":"k165","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k164","text":"Your provider brings all of this together into one clear recommendation.","marks":[]}]},{"_type":"block","_key":"k167","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k166","text":"Features That Pair With Different Styles","marks":["strong"]}]},{"_type":"block","_key":"k169","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k168","text":"Not every feature is available in every style. Your hearing needs also matter.","marks":[]}]},{"_type":"block","_key":"k16b","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16a","text":"Rechargeable power","marks":[]}]},{"_type":"block","_key":"k16d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16c","text":"Many behind-the-ear and RIC options support rechargeable batteries. This reduces battery changes and makes daily use easier.","marks":[]}]},{"_type":"block","_key":"k16f","style":"h3","markDefs":[{"_type":"link","_key":"phonaklink","href":"/phonak-hearing-aids/"}],"children":[{"_type":"span","_key":"k16e_lnk","text":"Bluetooth streaming","marks":["phonaklink"]}]},{"_type":"block","_key":"k16h","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16g","text":"Phone calls and media streaming are common in modern hearing aids. Style and brand can affect how strong and stable streaming feels.","marks":[]}]},{"_type":"block","_key":"k16j","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16i","text":"Speech support in noise","marks":[]}]},{"_type":"block","_key":"k16l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16k","text":"Noise control features help in restaurants and group talk. Your audiologist will match these tools to your hearing test results and listening goals.","marks":[]}]},{"_type":"block","_key":"k16n","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16m","text":"Tinnitus support","marks":[]}]},{"_type":"block","_key":"k16p","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16o","text":"Some hearing aids include sound options for tinnitus relief. This is most helpful when it is paired with a tinnitus plan and follow-up care.","marks":[]}]},{"_type":"block","_key":"k16r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16q","text":"Your plan should include more than a device choice. It should include proper fitting, fine-tuning, and support over time.","marks":[]}]},{"_type":"block","_key":"k16t","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k16s","text":"Why Hearing Aid Fitting and Verification Matter","marks":["strong"]}]},{"_type":"block","_key":"k16v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16u","text":"The same hearing aid can sound different in different ears. Ear shape changes how sound travels.","marks":[]}]},{"_type":"block","_key":"k16x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16w","text":"New Leaf Hearing Care uses professional fitting and verification, including Real Ear Measurements. This confirms that your hearing aids match your hearing needs in your ears, not in a lab.","marks":[]}]},{"_type":"block","_key":"k16z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16y","text":"This step helps speech sound clearer. It also helps the volume feel more comfortable.","marks":[]}]},{"_type":"block","_key":"k171","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k170","text":"What to Expect When You Get Hearing Aids At New Leaf Hearing Care","marks":["strong"]}]},{"_type":"block","_key":"k173","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k172","text":"Your visit starts with your hearing test results and your goals. We talk through the situations you want to improve first.","marks":[]}]},{"_type":"block","_key":"k175","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k174","text":"Then you will review hearing aid styles that fit your hearing needs and your budget. Feel free to ask questions, and our audiologists will make sure to give you honest and transparent answers.","marks":[]}]},{"_type":"block","_key":"k177","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k176","text":"After selection, we fit the devices, program them, and teach you how to use and care for them. Follow-up visits give you fine-tuning and support as your brain adjusts to new sounds.","marks":[]}]},{"_type":"block","_key":"k179","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k178","text":"Why Local Audiology Care Helps","marks":["strong"]}]},{"_type":"block","_key":"k17b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17a","text":"A hearing aid is not a one-time purchase. It is a health tool that needs long-term support.","marks":[]}]},{"_type":"block","_key":"k17d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17c","text":"New Leaf Hearing Care is locally owned and focused on people, not quotas. You get care built around your life and your comfort.","marks":[]}]},{"_type":"block","_key":"k17f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17e","text":"Both our locations offer the same patient-first approach. Littleton patients who knew Columbine Hearing Care will recognize the same commitment to quality care.","marks":[]}]},{"_type":"block","_key":"k17h","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k17g","text":"FAQs","marks":["strong"]}]},{"_type":"block","_key":"k17j","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17i","text":"What is the most common hearing aid style?","marks":["strong"]}]},{"_type":"block","_key":"k17l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17k","text":"Receiver-in-canal (RIC) hearing aids are one of the most common styles because they feel light, sound natural for many patients, and support modern features like streaming.","marks":[]}]},{"_type":"block","_key":"k17n","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17m","text":"How do I know which hearing aid style is right for me?","marks":["strong"]}]},{"_type":"block","_key":"k17p","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17o","text":"Your audiologist uses your hearing test results, ear shape, comfort needs, and daily listening goals to recommend the hearing aid style that fits your life and your hearing level.","marks":[]}]},{"_type":"block","_key":"k17r","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17q","text":"How does a hearing aid fitting work after I pick a style?","marks":["strong"]}]},{"_type":"block","_key":"k17t","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17s","text":"A fitting includes setting the device to match your hearing test, checking comfort and fit, teaching you how to use it, and scheduling follow-up visits for fine-tuning.","marks":[]}]},{"_type":"block","_key":"k17v","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17u","text":"What is the easiest hearing aid style to handle?","marks":["strong"]}]},{"_type":"block","_key":"k17x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17w","text":"Behind-the-ear (BTE) and in-the-ear (ITE) styles are often easier to handle because they are larger and simpler to insert, especially for people with limited finger strength.","marks":[]}]},{"_type":"block","_key":"k17z","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k17y","text":"Schedule a Hearing Aid Style Consultation","marks":["strong"]}]},{"_type":"block","_key":"k181","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k180","text":"The right choice becomes clear when you try options and talk with an audiologist. You deserve a plan that supports strong communication, confidence, and an active life.","marks":[]}]},{"_type":"block","_key":"k183","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k182","text":"Schedule a visit with New Leaf Hearing Care in Arvada, CO or Littleton, CO (formerly Columbine Hearing Care).","marks":[]}]},{"_type":"block","_key":"k185","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k184","text":"If you want expert help comparing hearing aid styles, start with a consultation that connects your hearing test, your needs, and your goals.","marks":[]}]}]' WHERE slug='hearing-aids-products/hearing-aid-styles' AND content='[{"_type":"block","_key":"k13v","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k13u","text":"A Quick Tip Before You Compare Styles","marks":["strong"]}]},{"_type":"block","_key":"k13x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k13w","text":"A hearing aid style should match your hearing test results. It should also match how you live, work, and move through the day.","marks":[]}]},{"_type":"block","_key":"k13z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k13y","text":"A good fit starts with a full hearing test and a real conversation. That is how the “best on paper” option becomes the best option for you.","marks":[]}]},{"_type":"block","_key":"k141","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k140","text":"The Main Hearing Aid Styles","marks":["strong"]}]},{"_type":"block","_key":"k143","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k142","text":"Most hearing aids fall into two broad groups.","marks":[]}]},{"_type":"block","_key":"k145","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k144","text":"Some styles sit behind the ear. Others sit in or near the ear canal.","marks":[]}]},{"_type":"block","_key":"k147","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k146","text":"Your audiologist will show you what each one feels like and how it works, then guide you toward the right match.","marks":[]}]},{"_type":"block","_key":"k149","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k148","text":"Behind-the-Ear (BTE)","marks":[]}]},{"_type":"block","_key":"k14b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14a","text":"A behind-the-ear hearing aid sits behind the ear. Sound travels through a small tube to an earmold or ear tip.","marks":[]}]},{"_type":"block","_key":"k14d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14c","text":"This style works for many levels of hearing loss. It also provides a stable fit for active days.","marks":[]}]},{"_type":"block","_key":"k14f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14e","text":"Many people like BTE styles because they feel secure. Cleaning can also feel simpler because the parts are easier to see and handle.","marks":[]}]},{"_type":"block","_key":"k14h","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14g","text":"Receiver-in-Canal (RIC)","marks":[]}]},{"_type":"block","_key":"k14j","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14i","text":"A receiver-in-canal style sits behind the ear, with a thin wire that connects to a small speaker in the ear canal.","marks":[]}]},{"_type":"block","_key":"k14l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14k","text":"RIC styles are popular because they feel light and open. Many people say the sound feels natural, especially for mild to moderate hearing loss.","marks":[]}]},{"_type":"block","_key":"k14n","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14m","text":"This style can also offer strong features for speech in noise and phone streaming. Your audiologist will help you choose the right receiver strength for your hearing needs.","marks":[]}]},{"_type":"block","_key":"k14p","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14o","text":"In-the-Ear (ITE)","marks":[]}]},{"_type":"block","_key":"k14r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14q","text":"An in-the-ear hearing aid sits inside the outer ear. The faceplate is visible, and the hearing aid is one piece.","marks":[]}]},{"_type":"block","_key":"k14t","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14s","text":"Some patients like ITE styles because they are easier to insert than smaller in-canal options. Handling can be simpler for people with limited finger strength.","marks":[]}]},{"_type":"block","_key":"k14v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14u","text":"ITE styles also keep everything in one place. That can feel less fussy for daily use.","marks":[]}]},{"_type":"block","_key":"k14x","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k14w","text":"In-the-Canal (ITC)","marks":[]}]},{"_type":"block","_key":"k14z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k14y","text":"An in-the-canal hearing aid sits partly in the ear canal. It is smaller than an ITE and less visible for many people.","marks":[]}]},{"_type":"block","_key":"k151","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k150","text":"Comfort and fit depend on your ear shape. Your audiologist will check if your ear canal size supports this option.","marks":[]}]},{"_type":"block","_key":"k153","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k152","text":"ITC styles can work well for people who want a smaller device while still keeping handling reasonable.","marks":[]}]},{"_type":"block","_key":"k155","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k154","text":"Completely-in-Canal (CIC)","marks":[]}]},{"_type":"block","_key":"k157","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k156","text":"A completely-in-canal hearing aid sits deeper in the ear canal and is designed to be less noticeable.","marks":[]}]},{"_type":"block","_key":"k159","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k158","text":"This style can be a good match for some people who want a discreet option. It requires good finger control for insertion and removal.","marks":[]}]},{"_type":"block","_key":"k15b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15a","text":"CIC styles also depend on ear canal shape and hearing needs. Your audiologist will confirm if this option fits your hearing profile.","marks":[]}]},{"_type":"block","_key":"k15d","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15c","text":"Hearing Aid Style Choice Is Not Only About Looks","marks":["strong"]}]},{"_type":"block","_key":"k15f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15e","text":"Many people start with “I want the smallest one.” That makes sense.","marks":[]}]},{"_type":"block","_key":"k15h","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15g","text":"However, daily success depends on comfort, clear sound, and easy use. A hearing aid that is hard to handle or does not match your hearing needs leads to less wear time.","marks":[]}]},{"_type":"block","_key":"k15j","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15i","text":"More wear time leads to better results. Our audiologists in Littleton, CO and Arvada, CO will help you choose a style you will use every day.","marks":[]}]},{"_type":"block","_key":"k15l","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15k","text":"Your Hearing Needs + Your Routine = The Right Style","marks":["strong"]}]},{"_type":"block","_key":"k15n","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15m","text":"Style choice is part hearing, part lifestyle. When choosing the best hearing aid style, we need to consider the following:","marks":[]}]},{"_type":"block","_key":"k15p","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15o","text":"Dexterity and vision","marks":[]}]},{"_type":"block","_key":"k15r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15q","text":"Small batteries and small buttons can be tough. Rechargeable options and larger styles can make daily use easier.","marks":[]}]},{"_type":"block","_key":"k15t","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15s","text":"Glasses and masks","marks":[]}]},{"_type":"block","_key":"k15v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15u","text":"Behind-the-ear styles can still work well with glasses. Your audiologist can adjust the fit and show you how to put them on in the right order.","marks":[]}]},{"_type":"block","_key":"k15x","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k15w","text":"Work and hobbies","marks":[]}]},{"_type":"block","_key":"k15z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k15y","text":"Meetings, phone calls, and noisy jobs require strong speech support. Music, fitness, and outdoor time can affect comfort needs.","marks":[]}]},{"_type":"block","_key":"k161","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k160","text":"Ear shape and comfort","marks":[]}]},{"_type":"block","_key":"k163","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k162","text":"Some ears do best with soft tips. Others need custom earmolds for a secure seal and stable sound.","marks":[]}]},{"_type":"block","_key":"k165","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k164","text":"Your provider brings all of this together into one clear recommendation.","marks":[]}]},{"_type":"block","_key":"k167","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k166","text":"Features That Pair With Different Styles","marks":["strong"]}]},{"_type":"block","_key":"k169","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k168","text":"Not every feature is available in every style. Your hearing needs also matter.","marks":[]}]},{"_type":"block","_key":"k16b","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16a","text":"Rechargeable power","marks":[]}]},{"_type":"block","_key":"k16d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16c","text":"Many behind-the-ear and RIC options support rechargeable batteries. This reduces battery changes and makes daily use easier.","marks":[]}]},{"_type":"block","_key":"k16f","style":"h3","markDefs":[{"_type":"link","_key":"phonaklink","href":"/phonak-hearing-aids/"}],"children":[{"_type":"span","_key":"k16e_lnk","text":"Bluetooth streaming","marks":["phonaklink"]}]},{"_type":"block","_key":"k16h","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16g","text":"Phone calls and media streaming are common in modern hearing aids. Style and brand can affect how strong and stable streaming feels.","marks":[]}]},{"_type":"block","_key":"k16j","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16i","text":"Speech support in noise","marks":[]}]},{"_type":"block","_key":"k16l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16k","text":"Noise control features help in restaurants and group talk. Your audiologist will match these tools to your hearing test results and listening goals.","marks":[]}]},{"_type":"block","_key":"k16n","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k16m","text":"Tinnitus support","marks":[]}]},{"_type":"block","_key":"k16p","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16o","text":"Some hearing aids include sound options for tinnitus relief. This is most helpful when it is paired with a tinnitus plan and follow-up care.","marks":[]}]},{"_type":"block","_key":"k16r","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16q","text":"Your plan should include more than a device choice. It should include proper fitting, fine-tuning, and support over time.","marks":[]}]},{"_type":"block","_key":"k16t","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k16s","text":"Why Hearing Aid Fitting and Verification Matter","marks":["strong"]}]},{"_type":"block","_key":"k16v","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16u","text":"The same hearing aid can sound different in different ears. Ear shape changes how sound travels.","marks":[]}]},{"_type":"block","_key":"k16x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16w","text":"New Leaf Hearing Care uses professional fitting and verification, including Real Ear Measurements. This confirms that your hearing aids match your hearing needs in your ears, not in a lab.","marks":[]}]},{"_type":"block","_key":"k16z","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k16y","text":"This step helps speech sound clearer. It also helps the volume feel more comfortable.","marks":[]}]},{"_type":"block","_key":"k171","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k170","text":"What to Expect When You Get Hearing Aids At New Leaf Hearing Care","marks":["strong"]}]},{"_type":"block","_key":"k173","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k172","text":"Your visit starts with your hearing test results and your goals. We talk through the situations you want to improve first.","marks":[]}]},{"_type":"block","_key":"k175","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k174","text":"Then you will review hearing aid styles that fit your hearing needs and your budget. Feel free to ask questions, and our audiologists will make sure to give you honest and transparent answers.","marks":[]}]},{"_type":"block","_key":"k177","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k176","text":"After selection, we fit the devices, program them, and teach you how to use and care for them. Follow-up visits give you fine-tuning and support as your brain adjusts to new sounds.","marks":[]}]},{"_type":"block","_key":"k179","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k178","text":"Why Local Audiology Care Helps","marks":["strong"]}]},{"_type":"block","_key":"k17b","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17a","text":"A hearing aid is not a one-time purchase. It is a health tool that needs long-term support.","marks":[]}]},{"_type":"block","_key":"k17d","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17c","text":"New Leaf Hearing Care is locally owned and focused on people, not quotas. You get care built around your life and your comfort.","marks":[]}]},{"_type":"block","_key":"k17f","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17e","text":"Both our locations offer the same patient-first approach. Littleton patients who knew Columbine Hearing Care will recognize the same commitment to quality care.","marks":[]}]},{"_type":"block","_key":"k17h","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k17g","text":"FAQs","marks":["strong"]}]},{"_type":"block","_key":"k17j","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17i","text":"What is the most common hearing aid style?","marks":["strong"]}]},{"_type":"block","_key":"k17l","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17k","text":"Receiver-in-canal (RIC) hearing aids are one of the most common styles because they feel light, sound natural for many patients, and support modern features like streaming.","marks":[]}]},{"_type":"block","_key":"k17n","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17m","text":"How do I know which hearing aid style is right for me?","marks":["strong"]}]},{"_type":"block","_key":"k17p","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17o","text":"Your audiologist uses your hearing test results, ear shape, comfort needs, and daily listening goals to recommend the hearing aid style that fits your life and your hearing level.","marks":[]}]},{"_type":"block","_key":"k17r","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17q","text":"How does a hearing aid fitting work after I pick a style?","marks":["strong"]}]},{"_type":"block","_key":"k17t","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17s","text":"A fitting includes setting the device to match your hearing test, checking comfort and fit, teaching you how to use it, and scheduling follow-up visits for fine-tuning.","marks":[]}]},{"_type":"block","_key":"k17v","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k17u","text":"What is the easiest hearing aid style to handle?","marks":["strong"]}]},{"_type":"block","_key":"k17x","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17w","text":"Behind-the-ear (BTE) and in-the-ear (ITE) styles are often easier to handle because they are larger and simpler to insert, especially for people with limited finger strength.","marks":[]}]},{"_type":"block","_key":"k17z","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k17y","text":"Schedule a Hearing Aid Style Consultation","marks":["strong"]}]},{"_type":"block","_key":"k181","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k180","text":"The right choice becomes clear when you try options and talk with an audiologist. You deserve a plan that supports strong communication, confidence, and an active life.","marks":[]}]},{"_type":"block","_key":"k183","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k182","text":"Schedule a visit with New Leaf Hearing Care in Arvada, CO or Littleton, CO (formerly Columbine Hearing Care).","marks":[]}]},{"_type":"block","_key":"k185","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k184","text":"If you want expert help comparing hearing aid styles, start with a consultation that connects your hearing test, your needs, and your goals.","marks":[]}]}]';
UPDATE ec_internal_pages SET intro_content='[{"_type":"block","_key":"knn","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"knm","text":"Hearing aid accessories are add-ons and care tools that improve how your hearing aids sound, connect, and hold up day to day.","marks":[]}]},{"_type":"block","_key":"knp","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kno","text":"The right hearing aid accessory helps you hear speech more clearly in tough places, stay connected to devices, and keep your hearing aids working well.","marks":[]}]},{"_type":"block","_key":"knr","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"knq","text":"New Leaf Hearing Care offers personalized hearing aid accessories in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"knt","style":"normal","markDefs":[{"_type":"link","_key":"nlfit263","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"knt_f0","text":"Hearing aid accessories help fix the real-world problems that can show up after a fitting. Even a well-programmed hearing aid can struggle in a loud restaurant, a meeting room, or during a car ride, where noise and distance make speech harder to follow. If your devices aren''t set up yet, start with a professional fitting. New Leaf Hearing Care provides ","marks":[]},{"_type":"span","_key":"knt_f1","text":"hearing aid fitting appointment in Arvada","marks":["nlfit263"]},{"_type":"span","_key":"knt_f2","text":" and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"knv","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"knu","text":"New Leaf Hearing Care helps you choose accessories that match your hearing goals and your routine. The goal stays simple: clearer speech, easier use, and fewer daily hassles.","marks":[]}]},{"_type":"block","_key":"knx","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"knw","text":"You can schedule an appointment with our trusted audiologists in Arvada, CO or Littleton, CO. The Littleton location is formerly known as Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]' WHERE slug='hearing-aids-products/hearing-aid-accessories' AND intro_content='[{"_type":"block","_key":"knn","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"knm","text":"Hearing aid accessories are add-ons and care tools that improve how your hearing aids sound, connect, and hold up day to day.","marks":[]}]},{"_type":"block","_key":"knp","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kno","text":"The right hearing aid accessory helps you hear speech more clearly in tough places, stay connected to devices, and keep your hearing aids working well.","marks":[]}]},{"_type":"block","_key":"knr","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"knq","text":"New Leaf Hearing Care offers personalized hearing aid accessories in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"knt","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kns","text":"Hearing aid accessories help fix the real-world problems that can show up after a fitting. Even a well-programmed hearing aid can struggle in a loud restaurant, a meeting room, or during a car ride, where noise and distance make speech harder to follow.","marks":[]}]},{"_type":"block","_key":"knv","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"knu","text":"New Leaf Hearing Care helps you choose accessories that match your hearing goals and your routine. The goal stays simple: clearer speech, easier use, and fewer daily hassles.","marks":[]}]},{"_type":"block","_key":"knx","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"knw","text":"You can schedule an appointment with our trusted audiologists in Arvada, CO or Littleton, CO. The Littleton location is formerly known as Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]';
UPDATE ec_hearing_aids SET intro_content='[{"_type":"block","_key":"k2rq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2rp","text":"Phonak hearing aids are modern devices built to support clearer speech and easier listening across many ages and hearing needs.","marks":[]}]},{"_type":"block","_key":"k2rs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2rr","text":"Phonak offers options for advanced sound processing, rechargeability, Bluetooth connectivity, and solutions for single-sided hearing loss, plus add-on microphones for noise and distance.","marks":[]}]},{"_type":"block","_key":"k2ru","style":"normal","listItem":"bullet","level":1,"markDefs":[{"_type":"link","_key":"nlfit222","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"k2ru_f0","text":"New Leaf Hearing Care provides ","marks":[]},{"_type":"span","_key":"k2ru_f1","text":"Phonak hearing aid fittings and support in Arvada, CO","marks":["nlfit222"]},{"_type":"span","_key":"k2ru_f2","text":" and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"k2rw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2rv","text":"Phonak’s philosophy on hearing healthcare keeps the patient at the center of everything they do. Their motto of “Well-Hearing is Well-Being” speaks for itself. Regardless of age, Phonak is a leader in the hearing industry in creating state-of-the-art technology for individuals of all ages.","marks":[]}]},{"_type":"block","_key":"k2ry","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2rx","text":"They value the importance of hearing from infancy through adulthood, as communication is the heartbeat of connection. Hearing health is about so much more than your ears—it affects your social, emotional, cognitive, and physical well-being.","marks":[]}]}]' WHERE slug='phonak-hearing-aids' AND intro_content='[{"_type":"block","_key":"k2rq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2rp","text":"Phonak hearing aids are modern devices built to support clearer speech and easier listening across many ages and hearing needs.","marks":[]}]},{"_type":"block","_key":"k2rs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2rr","text":"Phonak offers options for advanced sound processing, rechargeability, Bluetooth connectivity, and solutions for single-sided hearing loss, plus add-on microphones for noise and distance.","marks":[]}]},{"_type":"block","_key":"k2ru","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2rt","text":"New Leaf Hearing Care provides Phonak hearing aid fittings and support in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"k2rw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2rv","text":"Phonak’s philosophy on hearing healthcare keeps the patient at the center of everything they do. Their motto of “Well-Hearing is Well-Being” speaks for itself. Regardless of age, Phonak is a leader in the hearing industry in creating state-of-the-art technology for individuals of all ages.","marks":[]}]},{"_type":"block","_key":"k2ry","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2rx","text":"They value the importance of hearing from infancy through adulthood, as communication is the heartbeat of connection. Hearing health is about so much more than your ears—it affects your social, emotional, cognitive, and physical well-being.","marks":[]}]}]';
UPDATE ec_hearing_aids SET intro_content='[{"_type":"block","_key":"k2la","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2l9","text":"Oticon hearing aids are advanced devices that support clearer speech and more natural sound, using modern processing built to help the brain make sense of what you hear.","marks":[]}]},{"_type":"block","_key":"k2lc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2lb","text":"Oticon offers multiple styles and tech levels, including options for rechargeability, Bluetooth streaming, tinnitus relief sounds, and solutions for single-sided hearing loss.","marks":[]}]},{"_type":"block","_key":"k2le","style":"normal","listItem":"bullet","level":1,"markDefs":[{"_type":"link","_key":"nlfit222","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"k2le_f0","text":"New Leaf Hearing Care provides ","marks":[]},{"_type":"span","_key":"k2le_f1","text":"Oticon hearing aid fittings and support in Arvada, CO","marks":["nlfit222"]},{"_type":"span","_key":"k2le_f2","text":" and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"k2lg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2lf","text":"Oticon is an industry leader in developing innovative technologies for people with hearing loss. Oticon’s solutions are designed to help you hear and communicate better, so you can enjoy life more fully. Their commitment and dedication to research and development translate to the incredible sound quality of their hearing aids. Oticon believes everyone should have access to the best hearing solutions available today.","marks":[]}]}]' WHERE slug='oticon-hearing-aids' AND intro_content='[{"_type":"block","_key":"k2la","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2l9","text":"Oticon hearing aids are advanced devices that support clearer speech and more natural sound, using modern processing built to help the brain make sense of what you hear.","marks":[]}]},{"_type":"block","_key":"k2lc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2lb","text":"Oticon offers multiple styles and tech levels, including options for rechargeability, Bluetooth streaming, tinnitus relief sounds, and solutions for single-sided hearing loss.","marks":[]}]},{"_type":"block","_key":"k2le","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2ld","text":"New Leaf Hearing Care provides Oticon hearing aid fittings and support in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"k2lg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2lf","text":"Oticon is an industry leader in developing innovative technologies for people with hearing loss. Oticon’s solutions are designed to help you hear and communicate better, so you can enjoy life more fully. Their commitment and dedication to research and development translate to the incredible sound quality of their hearing aids. Oticon believes everyone should have access to the best hearing solutions available today.","marks":[]}]}]';
